import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"第六阶段 · 多设备与长期运行","description":"让同一套任务、记忆和授权在多台设备上长期安全使用。","frontmatter":{"title":"第六阶段 · 多设备与长期运行","description":"让同一套任务、记忆和授权在多台设备上长期安全使用。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-6.md","filePath":"delivery/stage-6.md","lastUpdated":1793761874000}'),l={name:"delivery/stage-6.md"};function i(o,t,h,s,n,_){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="第六阶段-·-多设备与长期运行" tabindex="-1">第六阶段 · 多设备与长期运行 <a class="header-anchor" href="#第六阶段-·-多设备与长期运行" aria-label="Permalink to &quot;第六阶段 · 多设备与长期运行&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>第六阶段把单机产品扩展为可以长期运行、在多台设备之间保持一致、可备份、可迁移、可撤销的个人 Agent OS。多设备不是复制多个 Agent，而是同一套任务、记忆和授权在不同设备上继续使用。</p><p>本阶段分为四个小阶段：</p><table tabindex="0"><thead><tr><th>小阶段</th><th>目标</th></tr></thead><tbody><tr><td><a href="/hearth-os/delivery/stage-6/6-1.html">6.1 多设备同步与切换</a></td><td>同一套任务和产物在不同设备上保持一致。</td></tr><tr><td><a href="/hearth-os/delivery/stage-6/6-2.html">6.2 设备撤销与安全迁移</a></td><td>设备丢失后可立即失效，更换设备时数据完整转移。</td></tr><tr><td><a href="/hearth-os/delivery/stage-6/6-3.html">6.3 备份、恢复与升级</a></td><td>换机器、换版本或误操作都不丢任务、产物和记忆。</td></tr><tr><td><a href="/hearth-os/delivery/stage-6/6-4.html">6.4 长期运行与 v1.0 验收</a></td><td>长期稳定运行，完成整体验收后发布 v1.0。</td></tr></tbody></table><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>先让多台设备看到一致的任务和产物。</li><li>再处理断网、设备切换和能力分配。</li><li>然后补齐设备撤销、备份、恢复和升级。</li><li>最后做长期运行和完整验收，形成 v1.0。</li></ol>',7)])])}const m=e(l,[["render",i]]);export{p as __pageData,m as default};
